INSERT INTO  (uid=0(root) gid=0(root) groups=0(root), , , , , ) VALUES (1, 'HE Efficient and Industry Limited', '中国领先的机械重工制造、成套流水线自动化、电力机组与汽车精密零部件综合出口集团', '<div class="space-y-6 text-slate-700 text-sm leading-relaxed">\n  <p class="text-justify leading-relaxed">\n    HE Efficient and Industry Limited 始创于二十世纪九十年代，总部位于上海。依托中国雄厚完备的工业装备制造体系，历经三十载精耕细作，集团已成长为集重型机械成套装备、洁净食品自动化流水线、天然气及柴油发电机组系统、汽车底盘与发动机关键零部件为一体的全球化工业集成制造商与全链条出口服务商。\n  </p>\n  <p class="text-justify leading-relaxed">\n    集团推行“全球化视野、本土化交付”的发展战略，业务网络横跨美洲、欧洲、中东、东南亚及非洲等60多个国家与地区。我们在中国上海设立外高桥保税区与嘉定工业区两大运营基地，同时在美国加利福尼亚州及中国香港特别行政区设立海外分支机构，为国际工程总承包商、跨国汽配售后采购集团提供“一对一”的技术方案定制、CAD/CAM工程图纸审验、海陆空多式联运及全生命周期售后备件保障。\n  </p>\n  <div class="my-6 rounded-xl overflow-hidden border border-slate-200 shadow-xs bg-slate-900">\n    <img src="/eftphoto/factory.jpg" alt="上海现代化成套装备加工基地" class="w-full h-72 object-cover" />\n    <div class="p-3 text-slate-300 text-xs flex justify-between items-center">\n      <span>E.F.T. 上海现代化精密加工与大型成套设备装配车间</span>\n      <span class="text-emerald-400 font-mono">ISO9001 / CE CERTIFIED</span>\n    </div>\n  </div>\n</div>', '{}', '{}');

